477		Let $\mathcal D$ be a distribution on $(x, y_1, y_2) \in \mathcal X \times \mathcal Y_1 \times \mathcal Y_2$. For $i \in \{1,2\}$ let $\mathcal G_i$ be a collection of functions $g_i \colon \mathcal Y_i \to \mathcal R_i$ and let $\{(G_i)^x_g\}_{g \in \mathcal G_i}$ be families of measurements such that $\{(G_2)^x_g\}_g$ is projective for every $x$. Suppose further that for every pair $(x, y_1)$ of positive probability under the marginal of $\mathcal D$ on $\mathcal X \times \mathcal Y_1$ (the only pairs for which the conditional distribution of $y_2$ under $\mathcal D$ is defined; pairs of marginal probability zero are subject to no requirement) it holds that for $g_2 \ne g_2' \in \mathcal G_2$ the probability, on average over $y_2$ chosen from $\mathcal D$ conditioned on $(x, y_1)$, that $g_2(y_2) = g_2'(y_2)$ is at most $\eta$. Let $\{A^{x,y_1,y_2}_{a_1,\,a_2}\}$ be a family of projective measurements with outcomes $(a_1, a_2) \in \mathcal R_1 \times \mathcal R_2$ such that for $i \in \{1,2\}$,
478		\begin{equation}\label{eq:pasting-1}
479			A^{x,y_1,y_2}_{a_i} \ot \Id \simeq_\delta \Id \ot (G_i)^x_{[\operatorname{eval}_{y_i}(\cdot)=a_i]}
480		\end{equation}

 920	\end{equation}
 921	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
 922	\begin{equation*}
 923	J^x_{a_1, \ldots, a_k} := (B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k}.
 924	\end{equation*}
 925	Then
 926	\begin{equation*}
 927	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta^{1/2}} I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 928	\end{equation*}
 929	\end{fact}
 930	\begin{proof}
 931	For each $1 \leq i \leq k$, 
 932	\Cref{eq:no-take-only-throw} implies that
 933	\begin{equation*}
 934	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 935	\end{equation*}
 936	Now, we repeatedly apply this using \Cref{fact:add-a-proj}:
 937	\begin{align*}
 938	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
 939	& = (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k}})_{\reg{Alice}} \otimes I_{\reg{Bob}}\\
 940	& \approx_{\delta} (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k-1}})_{\reg{Alice}} \otimes ((B_k)^x_{a_k})_{\reg{Bob}}\\
 941	&\qquad\qquad\qquad \qquad \qquad \qquad \cdots\\
 942	& \approx_{\delta} I_{\reg{Alice}} \otimes ((B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k})_{\reg{Bob}}\\
 943	& = I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 944	\end{align*}
 945	The fact now follows from \Cref{fact:almost-agreement} and the fact that~$A$ is a projective measurement.
 946	\end{proof}
